// Stress harness: replicate the dispatch_watch INT test N times, report failures.
import 'dart:async';
import 'dart:convert';
import 'dart:io';

final fixtureRoot = Directory.systemTemp.createTempSync('dw-int-stress-');
int failures = 0;

String stubGh(String dir) {
  final bin = Directory('$dir/bin')..createSync(recursive: true);
  File('${bin.path}/gh').writeAsStringSync(r'''
#!/usr/bin/env bash
echo "$*" >> "$GH_LOG_FILE"
cmd="$1"; sub="$2"
jq_arg=""
args=("$@")
for ((i=0; i<$#; i++)); do
  if [ "${args[$i]}" = "--jq" ]; then jq_arg="${args[$((i+1))]}"; fi
done
apply_jq() { if [ -n "$jq_arg" ]; then jq -r "$jq_arg"; else cat; fi; }
case "$cmd" in
  workflow) : ;;
  run)
    case "$sub" in
      list)
        is_status=0
        for ((j = 0; j < ${#args[@]}; j++)); do
          if [ "${args[$j]}" = "--status" ]; then is_status=1; fi
        done
        if [ "$is_status" = "1" ]; then
          cat "$GH_STUB_DIR/siblings.json" 2>/dev/null | apply_jq
          exit 0
        fi
        cat "$GH_STUB_DIR/runs.json" | apply_jq
        ;;
      view)
        id="$3"
        if [ -f "$GH_STUB_DIR/cancelled-$id" ]; then
          status=completed; conclusion=cancelled; jobs_body=""
        else
          f="$GH_STUB_DIR/view-$id.txt"
          line=$(head -1 "$f")
          sed -i.bak '1d' "$f" && rm -f "$f.bak"
          if ! [ -s "$f" ]; then printf '%s\n' "$line" > "$f"; fi
          status="${line%% *}"; conclusion="${line#* }"
          jobs_body=""
          is_jobs=0
          for ((j = 0; j < ${#args[@]} - 1; j++)); do
            if [ "${args[$j]}" = "--json" ] && [[ "${args[$((j + 1))]}" == *jobs* ]]; then is_jobs=1; fi
          done
          if [ "$is_jobs" = "1" ]; then
            jf="$GH_STUB_DIR/jobs-$id.txt"
            if [ -f "$jf" ]; then
              n=$(head -1 "$jf")
              sed -i.bak '1d' "$jf" && rm -f "$jf.bak"
              if ! [ -s "$jf" ]; then printf '%s\n' "$n" > "$jf"; fi
            else
              n=1
            fi
            jobs_body=''
            i=0
            while [ "$i" -lt "$n" ] 2>/dev/null; do
              if [ -n "$jobs_body" ]; then jobs_body="$jobs_body,"; fi
              jobs_body="$jobs_body{\"status\":\"in_progress\"}"
              i=$((i + 1))
            done
          fi
        fi
        is_jobs=0
        for ((j = 0; j < ${#args[@]} - 1; j++)); do
          if [ "${args[$j]}" = "--json" ] && [[ "${args[$((j + 1))]}" == *jobs* ]]; then is_jobs=1; fi
        done
        if [ "$is_jobs" = "1" ]; then
          printf '{"status":"%s","conclusion":"%s","jobs":[%s]}' "$status" "$conclusion" "$jobs_body" | apply_jq
        else
          printf '{"status":"%s","conclusion":"%s"}' "$status" "$conclusion" | apply_jq
        fi
        ;;
      cancel)
        id="$3"
        : > "$GH_STUB_DIR/cancelled-$id"
        ;;
    esac
    ;;
esac
exit 0
''');
  Process.runSync('chmod', ['+x', '${bin.path}/gh']);
  return bin.path;
}

String runJson(List<Map<String, Object>> runs) => jsonEncode(runs);
Map<String, Object> run(int id, String title, String createdAt) => {
  'databaseId': id, 'createdAt': createdAt, 'displayTitle': title,
};
String iso(int seconds) {
  final utc = DateTime.now().toUtc().add(Duration(seconds: seconds)).toIso8601String();
  return '${utc.substring(0, 19)}Z';
}

Future<void> one(int i) async {
  final dir = Directory('${fixtureRoot.path}/run-$i')..createSync(recursive: true);
  final bin = stubGh(dir.path);
  File('${dir.path}/log').writeAsStringSync('');
  File('${dir.path}/runs.json').writeAsStringSync(runJson([run(777, 'office-addin-suite', iso(-2))]));
  File('${dir.path}/view-777.txt').writeAsStringSync('in_progress -\n');
  File('${dir.path}/jobs-777.txt').writeAsStringSync('0\n');
  File('${dir.path}/siblings.json').writeAsStringSync('[]');
  final process = await Process.start('bash', [
    '/home/runner/work/flutter_agent_harness/flutter_agent_harness/scripts/dispatch_and_watch.sh',
    'office-addin.yml',
  ], environment: {
    'PATH': '$bin:${Platform.environment['PATH']}',
    'GITHUB_REPOSITORY': 'OWNER/REPO',
    'GH_TOKEN': 'stub',
    'GH_STUB_DIR': dir.path,
    'GH_LOG_FILE': '${dir.path}/log',
    'DW_POLL_SECONDS': '1',
    'DW_APPEAR_POLL_SECONDS': '0',
    'DW_APPEAR_ATTEMPTS': '20',
    'DW_DIAG_SECONDS': '0',
  });
  final outBuf = StringBuffer();
  process.stdout.transform(utf8.decoder).listen(outBuf.write);
  process.stderr.transform(utf8.decoder).listen(outBuf.write);
  // wait for 2 view polls in the stub log
  final deadline = DateTime.now().add(Duration(seconds: 10));
  while (DateTime.now().isBefore(deadline)) {
    final log = File('${dir.path}/log').readAsStringSync();
    if ('${log} '.split('run view 777 --repo OWNER/REPO').length - 1 >= 2) break;
    await Future<void>.delayed(Duration(milliseconds: 10));
  }
  process.kill(ProcessSignal.sigint);
  final code = await process.exitCode.timeout(Duration(seconds: 30), onTimeout: () {
    process.kill(ProcessSignal.sigkill);
    return -9;
  });
  if (code != 130) {
    failures++;
    print('=== iteration $i: exit=$code (want 130) ===');
    print(outBuf.toString());
    print('--- stub log tail ---');
    final lines = File('${dir.path}/log').readAsLinesSync();
    print(lines.length <= 12 ? lines.join('\n') : lines.sublist(lines.length - 12).join('\n'));
    final cancelled = Directory(dir.path).listSync().whereType<File>()
      .where((f) => f.uri.pathSegments.last.startsWith('cancelled-')).length;
    print('--- cancelled-777 exists: ${cancelled > 0}');
  }
}

Future<void> main(List<String> args) async {
  final n = args.isEmpty ? 30 : int.parse(args.first);
  for (var i = 1; i <= n; i++) {
    await one(i);
  }
  print('DONE: $n iterations, $failures failures');
}
