// TEMPORARY debug scratch — merge-conflict investigation (delete after).
// Logs every model call with the context the call sees, plus the
// post-interrupt estimate, so the merged vs parent behavior can be diffed.
import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

class LoggingScriptedThenHang {
  LoggingScriptedThenHang(this.scripted, {this.hangFromCall = 1 << 30});

  final List<List<AssistantMessageEvent>> scripted;
  var calls = 0;
  int hangFromCall;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    final n = ++calls;
    final chars = context.messages
        .map((m) => m.toString().length)
        .fold<int>(0, (a, b) => a + b);
    // ignore: avoid_print
    print('DBG call=$n msgs=${context.messages.length} chars=$chars '
        'hang=${n >= hangFromCall}');
    final stream = AssistantMessageEventStream();
    if (n < hangFromCall || n > scripted.length) {
      for (final event in scripted[n - 1]) {
        stream.push(event);
      }
      stream.end();
      return stream;
    }
    stream.push(StartEvent(partial: testAssistant()));
    cancelToken?.onCancel.then((_) {
      stream.push(
        ErrorEvent(
          reason: StopReason.aborted,
          error: testAssistant(
            stopReason: StopReason.aborted,
            errorMessage: 'Operation aborted',
          ),
        ),
      );
      stream.end();
    });
    return stream;
  }
}

void main() {
  test(
    'DBG: interrupt during post-run compaction — call trace',
    timeout: const Timeout(Duration(seconds: 120)),
    () async {
      final env = MemoryExecutionEnv(cwd: '/work');
      await env.writeFile('/work/.fah/memory/.last_maintenance', '');
      env.writeFile('big.txt', List.filled(1000, 'x' * 45).join('\n'));
      final io = FakeCliIO();
      final fake = LoggingScriptedThenHang([
        toolTurn([
          const ToolCall(
            id: 't1',
            name: 'read',
            arguments: {'path': 'big.txt'},
          ),
        ]),
        textTurn('first answer'),
        textTurn('unused — call 3 is the cancelled post-run summarizer'),
        textTurn('second answer'),
      ], hangFromCall: 3);
      final cli = AgentCli(
        config: AgentCliConfig(
          model: const Model(
            id: 'post-run-window',
            api: 'test-api',
            provider: 'test-provider',
            baseUrl: 'https://example.test',
            contextWindow: 32768,
            maxTokens: 4096,
          ),
          apiKey: '[REDACTED:Sensitive Value]',
          env: env,
          sessionRoot: '/sessions',
          providerKind: 'openai-completions',
          compactionEngine: CompactionEngine.classic,
          compactionSettings: const CompactionSettings(
            enabled: true,
            reserveTokens: 20768,
            keepRecentTokens: 200,
          ),
        ),
        io: io,
        streamFunction: fake.call,
      );
      final run = cli.run();

      io.sendLine('go');
      await waitForIt(
        () => fake.calls >= 3,
        reason: 'turn 1 completed and the post-run compaction started',
      );
      io.interrupt();
      await waitForIt(
        () => io.out.toString().contains('compaction interrupted'),
        reason: 'the interrupt receipt',
      );
      // ignore: avoid_print
      print('DBG after-interrupt calls=${fake.calls}');
      fake.hangFromCall = 1 << 30;
      io.sendLine('again');
      await waitForIt(
        () => io.out.toString().contains('RangeError') ||
            (fake.calls >= 4 && !cli.isBusy),
        reason: 'follow-up turn settles (or the known RangeError lands)',
      );
      // ignore: avoid_print
      print('DBG after-again calls=${fake.calls}');
      // ignore: avoid_print
      print('DBG tail=${io.out.toString().substring(
        io.out.toString().length > 900 ? io.out.toString().length - 900 : 0,
      ).replaceAll('\n', ' | ')}');
      io.sendLine('/exit');
      await run;
      await io.close();
    },
  );
}

